  const BRIDGE_SENTINEL = '__glimpse_bridge__';

  class BridgeSocket {
    constructor() {
      this.readyState = WebSocket.CONNECTING;
      this.onopen = null;
      this.onmessage = null;
      this.onerror = null;
      this.onclose = null;

      this._messageListener = (event) => this._handlePageMessage(event);
      window.addEventListener('message', this._messageListener);

      // Ask the service worker for an initial state snapshot — and trigger a
      // connect attempt if it isn't already up. If the SW is already connected,
      // we'll get back readyState=OPEN and synthesize an 'open' event so the
      // page's onopen handler fires identically to a real WebSocket lifecycle.
      try {
        window.postMessage(
          {
            [BRIDGE_SENTINEL]: true,
            direction: 'page-to-sw',
            kind: 'request_connect',
            correlationId: 'bridge-init',
          },
          '*'
        );
      } catch (e) {
        // Will retry via the page-level reconnect loop.
      }
    }

    _handlePageMessage(event) {
      if (event.source !== window) return;
      const msg = event.data;
      if (!msg || msg[BRIDGE_SENTINEL] !== true) return;
      if (msg.direction !== 'sw-to-page') return;
      const payload = msg.payload;
      if (!payload) return;

      if (payload.type === 'ws_message') {
        if (typeof this.onmessage === 'function') {
          try {
            this.onmessage({ data: payload.data });
          } catch (e) {
            console.error('[GLIMPSE Cache] onmessage handler threw:', e);
          }
        }
        return;
      }

      if (payload.type === 'bridge_event') {
        if (payload.event === 'open') {
          this.readyState = WebSocket.OPEN;
          try { mdTrace('bridge_event.open'); } catch (e) { /* trace-safe */ }
          if (typeof this.onopen === 'function') {
            try { this.onopen({}); } catch (e) { console.error('[GLIMPSE Cache] onopen threw:', e); }
          }
        } else if (payload.event === 'close') {
          this.readyState = WebSocket.CLOSED;
          try { mdTrace('bridge_event.close'); } catch (e) { /* trace-safe */ }
          if (typeof this.onclose === 'function') {
            try { this.onclose({}); } catch (e) { console.error('[GLIMPSE Cache] onclose threw:', e); }
          }
          window.removeEventListener('message', this._messageListener);
        }
        return;
      }

      if (payload.type === 'bridge_response') {
        // Synthesize lifecycle events from response-state if we haven't yet
        // emitted them. This catches the case where the SW was already
        // connected before this BridgeSocket existed — no separate 'open'
        // bridge_event will fire, so we promote ourselves to OPEN here.
        if (typeof payload.readyState === 'number') {
          const prevState = this.readyState;
          this.readyState = payload.readyState;
          if (prevState !== payload.readyState) {
            try { mdTrace('bridge_response.readyState', { prevState, newState: payload.readyState }); } catch (e) { /* trace-safe */ }
          }
          if (
            prevState !== WebSocket.OPEN &&
            payload.readyState === WebSocket.OPEN &&
            typeof this.onopen === 'function'
          ) {
            try { this.onopen({}); } catch (e) { console.error('[GLIMPSE Cache] onopen threw:', e); }
          }
          if (
            prevState === WebSocket.OPEN &&
            payload.readyState !== WebSocket.OPEN &&
            typeof this.onclose === 'function'
          ) {
            try { this.onclose({}); } catch (e) { console.error('[GLIMPSE Cache] onclose threw:', e); }
            window.removeEventListener('message', this._messageListener);
          }
        }
        return;
      }
    }

    send(data) {
      // Mirror native WebSocket.send semantics: if not open, native sockets
      // throw a DOMException 'InvalidStateError'. We surface the same shape
      // so existing try/catch sites behave identically.
      if (this.readyState !== WebSocket.OPEN) {
        throw new DOMException(
          'BridgeSocket is not open: readyState ' + this.readyState,
          'InvalidStateError'
        );
      }
      try {
        window.postMessage(
          {
            [BRIDGE_SENTINEL]: true,
            direction: 'page-to-sw',
            kind: 'send',
            payload: data,
          },
          '*'
        );
      } catch (e) {
        console.error('[GLIMPSE Cache] BridgeSocket.send postMessage threw:', e);
        throw e;
      }
    }

    close() {
      // Cooperative close — we cannot actually close the SW's WebSocket from
      // here (that's a global resource). Just detach our listener and mark
      // ourselves closed so the page logic moves on. The page's reconnect
      // timer will create a fresh BridgeSocket which will pick the SW's
      // current state back up.
      this.readyState = WebSocket.CLOSED;
      try {
        window.removeEventListener('message', this._messageListener);
      } catch (e) { /* no-op */ }
      if (typeof this.onclose === 'function') {
        try { this.onclose({}); } catch (e) { /* no-op */ }
      }
    }
  }

