  // 1-2-node tree stops wasting vertical space the rendered Markdown can use.
  const DOCK_LIST_MIN_PX = 28;
  const DEFAULT_DOCK_TOP_OFFSET_PX = 100; // clears Workflowy's search box
  const DOCK_MIN_HEIGHT = 200;
  const DEFAULT_DOCK_HEIGHT = 400;
