      getEndpointId: () => { try { return getEndpointId(); } catch (e) { return null; } },
      isDefaultTab: () => { let my = null; try { my = getEndpointId(); } catch (e) { my = null; } return !!my && brokerDefaultEndpointId === my; },
      toggleDefaultTab,
      markAliasEdited: () => { endpointAliasBoxEdited = true; },
      commitAlias: (inputEl, explicit) => commitEndpointAliasBox(inputEl, explicit === true),
      bindAliasInput: (inputEl) => { endpointAliasInputEl = inputEl; try { syncEndpointAliasBox(); } catch (e) { /* ignore */ } },
      savedTabsExport: () => Promise.resolve(openSavedTabsExportPopup()).catch((e) => setSavedTabsStatus('Export failed: ' + ((e && e.message) ? e.message : String(e)), false)),
