    dockedPanelEl = r.body;
    dockedListEl = r.outline;
    dockedRenderEl = r.render;
    dockedWarnEl = r.warn;
    _sliceSyncStatusEl = r.sync;
    dockedFreezeNoteEl = r.freezeNote;
    dockedStatusFooterEl = r.foot;
