      // halo bullet modifier, then the 'collapsed' row class.
      var bulletEl = el.querySelector(':scope > .name .bullet, :scope > .bullet');
      if (bulletEl && /\bbullet--show-halo\b/i.test(bulletEl.className || '')) return true;
      if (/\bcollapsed\b/i.test(el.className || '')) return true;
