    const rootUuid = spec.root_uuid || null;
    const lightning = (spec.lightning && typeof spec.lightning === 'object' && spec.lightning.mode)
      ? spec.lightning : null;
    const matchScope = (String(spec.match_scope || '').trim().toLowerCase() === 'name')
      ? 'name' : 'name_and_note';
    const _specDescendPolicy = (String(spec.descend_policy || '').trim().toLowerCase() === 'stop_at_child_anchors')
      ? 'stop_at_child_anchors' : 'all';
    // SERVER-SIDE SCOPE: rootUuid (optional) re-projects the SAME scope this
    // dock was rendered from -- a bare RAW-DUMP root (groupId null), or a
    // slice override root (groupId present). MUST match what the full-document
