    tagsInput.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') { ev.preventDefault(); doSubmit(); } });
    sinceInput.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') { ev.preventDefault(); doSubmit(); } });

