      const _present = isRowMaterialized(uuid);
      let _it = null; try { _it = WF.getItemById(uuid); } catch (e) {}
      let _exp = null; try { _exp = (_it && typeof _it.isExpanded === 'function') ? _it.isExpanded() : null; } catch (e) {}
      // (f) DOM-PRESENCE GATE (Dan, July 2026 -- the deterministic fix). Fire an
      // expand ONLY when this node's row is CURRENTLY MATERIALIZED in the
      // Workflowy DOM. Empirically established (two live probes: parent-collapse
      // AND search-hidden) that a node's `div[projectid="<uuid>"]` element is
      // REMOVED from the DOM whenever the node is out of view -- so DOM presence
      // is a single, method-independent, SYNCHRONOUS truth for 'is this node
