      // materializes. This replaces the old blind model-fire + the bounded
      // initial-settle timer with an event-driven, heuristic-free rule.
      if (!isRowMaterialized(uuid)) { return; }        // not in view yet -> stay pending.
      let item = null;
      try { item = WF.getItemById(uuid); } catch (e) { pendingExpand.delete(uuid); return; }
