      const rid = `mergeslice-${Date.now()}-${++mergeSliceGroupsReqCounter}`;
      const timer = setTimeout(() => {
        pendingMergeSliceGroups.delete(rid);
        resolve({ success: false, error: 'merge_slice_groups request timed out.' });
      }, timeoutMs);
      pendingMergeSliceGroups.set(rid, { resolve, timer });
