  function renderDockedSelectionLocal(/* projectEl, rawNote */) {
    if (!dockedRenderEl) return;
    mdTrace('renderLocal.enter', { paneHasGood: !!dockedPaneHasGoodContent });
    // NON-DESTRUCTIVE: if the pane already holds ANY good rendered content,
    // a transport/timeout failure is a pure no-op. Last-known-good is sacred.
    if (dockedPaneHasGoodContent) {
      mdTrace('renderLocal.noOp_preserveLastGood');
      return;
    }
    // COLD START ONLY: the pane has never rendered anything; show the
    // actionable message so the user isn't staring at a blank dock.
    mdTrace('renderLocal.coldStart_paintingUnavailable');
    const msg = 'GLIMPSE server unavailable — the Markdown modal renders on the '
      + 'server. Reconnect / wait for the broker, then click the row again (or '
      + 'press Refresh).';
    dockedRenderEl.innerHTML = composedMarkdownToHtml('⚠ ' + msg);
    dockedRenderEl.scrollTop = 0;
    setDockedRenderedSource('⚠ ' + msg);
    dockedRenderedGoodUuid = null;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Provable-completeness suppression of the scroll-to-bottom warning
  // (Dan, June 2026)
  // ─────────────────────────────────────────────────────────────────────────
  //
  // The yellow warning exists because Workflowy virtualizes large outlines:
  // nodes BELOW the viewport may not be in the DOM until you scroll down, so a
  // DOM-walked slice could be silently truncated at the bottom. But there is a
  // case where truncation is PROVABLY impossible: when the rendered selection
  // is some node N whose SUBTREE is what we display, and the underlying list
  // (the live Workflowy DOM when unfrozen, or the frozen snapshot rows when
  // frozen) contains AT LEAST ONE node AFTER N's entire subtree — a following
  // sibling of N, or a following sibling of any ancestor of N (a 'promoted'
  // node that comes after the whole subtree). If such a node exists, we are
  // literally looking at content past the end of what N's subtree renders, so
  // nothing below could be missing — the warning is irrelevant and we hide it.
  //
