            root_uuid: rootScope || null,
            group_name: res.group_name,
            node_count: res.node_count,
            rows: res.rows,
            renders: res.renders,
            render_mode: res.render_mode,
            // TIER-2 live-GUI-sync fields (Dan, July 2026 BUG FIX): same fix as
            // the Apply call site -- forward the server's search_string_to_issue
